function validLesson(id,s,body){
 if(!Object.prototype.hasOwnProperty.call(lessonRules,id)||!allowedKeys(body,['worksheetId','snapshot','message','history','coachingStyle','narrativeConsent']))return false;
 if(Object.prototype.hasOwnProperty.call(batch1Kinds,id)){
  if(body.narrativeConsent!==true || !allowedKeys(s,['kind','values']) || s.kind!==batch1Kinds[id] || !s.values || typeof s.values!=='object' || Array.isArray(s.values))return false;
  const fields=Object.entries(s.values);
  return fields.length<=45 && fields.every(([k,v])=>/^[a-zA-Z][a-zA-Z0-9_]{0,40}$/.test(k) && (v===null || (typeof v==='number'&&Number.isFinite(v)&&Math.abs(v)<=1e9) || bounded(v,300) || (Array.isArray(v)&&v.length<=8&&v.every(x=>typeof x==='number'&&Number.isFinite(x)&&Math.abs(x)<=1e9))));
 }
 if(id==='affordability-test'){
  if(!allowedKeys(s,['kind','salary','loadingFactor','rampMonths','cashOnHand','monthlyNetBurn','hasRampReasoning','hasTimingPlan'])||s.kind!=='hire-affordability')return false;
  return ['salary','loadingFactor','rampMonths','cashOnHand','monthlyNetBurn'].every(k=>s[k]===null||(typeof s[k]==='number'&&Number.isFinite(s[k])&&s[k]>=0&&s[k]<=1e9))&&s.loadingFactor!==0&&typeof s.hasRampReasoning==='boolean'&&typeof s.hasTimingPlan==='boolean';
 }
 if(body.narrativeConsent!==true)return false;
 if(id==='business-model-canvas')return allowedKeys(s,['kind','test','riskRationale','hasResults'])&&s.kind==='business-model-canvas'&&allowedKeys(s.test,['who','action','rejectionCriterion','dueDate'])&&bounded(s.test.who,400)&&bounded(s.test.action,400)&&bounded(s.test.rejectionCriterion,400)&&bounded(s.test.dueDate,20)&&bounded(s.riskRationale,600)&&typeof s.hasResults==='boolean';
 const keys=['lever_scope','lever_proximity','lever_speed','lever_stake','pitch_owns','pitch_90','pitch_2y','fit_norms','fit_complement'];
 return allowedKeys(s,['kind','fields'])&&s.kind==='recruiting-plan'&&allowedKeys(s.fields,keys)&&Object.keys(s.fields).length===9&&Object.values(s.fields).every(v=>bounded(v,500));
}

// Server-side arithmetic: avoid language-model errors in cumulative cash and receipt-delay scenarios.
function cashTimingAnalysis(snapshot) {
  const v=snapshot.values;
  const opening=v.openingBalance;
  const inflows=v.weeklyInflows, outflows=v.weeklyOutflows;
  if (typeof opening!=="number" || !Number.isFinite(opening) || opening<0 ||
      !Array.isArray(inflows) || !Array.isArray(outflows) || inflows.length!==8 || outflows.length!==8 ||
      ![...inflows,...outflows].every(x=>typeof x==="number"&&Number.isFinite(x)&&x>=0)) return null;
  let cash=opening;
  const weeks=inflows.map((cashIn,i)=>{
    const start=cash;
    cash=start+cashIn-outflows[i];
    return {week:i+1,opening:start,cashIn,cashOut:outflows[i],closing:cash};
  });
  const low=weeks.reduce((a,b)=>b.closing<a.closing?b:a);
  const totalIn=inflows.reduce((a,b)=>a+b,0),totalOut=outflows.reduce((a,b)=>a+b,0);
  const delayedReceipts=[];
  for(let i=0;i<8;i++){
    if(inflows[i]<=0)continue;
    for(const delay of [1,2,3]){
      const shifted=inflows.slice();shifted[i]-=inflows[i];
      if(i+delay<8)shifted[i+delay]+=inflows[i];
      let bal=opening,min=Infinity,minWeek=0;
      for(let w=0;w<8;w++){bal+=shifted[w]-outflows[w];if(bal<min){min=bal;minWeek=w+1;}}
      delayedReceipts.push({receiptWeek:i+1,amount:inflows[i],delayWeeks:delay,receivedWithinHorizon:i+delay<8,lowestClosing:min,lowestWeek:minWeek,dropInLowestClosing:low.closing-min});
    }
  }
  delayedReceipts.sort((a,b)=>b.dropInLowestClosing-a.dropInLowestClosing||b.amount-a.amount);
  return {openingBalance:opening,weeks,lowestClosing:low.closing,lowestWeek:low.week,totalInflows:totalIn,totalOutflows:totalOut,endingCash:cash,largestTimingExposures:delayedReceipts.slice(0,6),note:"These are aggregate cash movements, not confirmed customer payments. Delayed receipts are shifted, not permanently lost; if beyond week 8 they fall outside the modeled horizon. No cash safety threshold was supplied."};
}

const json = (data, status=200, headers={}) => new Response(JSON.stringify(data), {status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store',...headers}});
function validSnapshot(s){
  return s && Array.isArray(s.weeks) && s.weeks.length===13 && s.weeks.every((w,i)=>w.week===i+1 && ['opening','cashIn','cashOut','closing'].every(k=>Number.isFinite(w[k]) && Math.abs(w[k])<1e12) && Math.abs(w.opening+w.cashIn-w.cashOut-w.closing)<0.011) && s.weeks.every((w,i)=>i===0||Math.abs(w.opening-s.weeks[i-1].closing)<0.011);
}
